<?php declare(strict_types=1);final class TaskStateMachine{private const T=['pending'=>['ready','waiting_user','waiting_dependency','cancelled'],'ready'=>['running','waiting_dependency','cancelled'],'running'=>['waiting_user','waiting_dependency','completed','failed','cancelled'],'waiting_user'=>['ready','cancelled'],'waiting_dependency'=>['ready','failed','cancelled'],'failed'=>['ready','cancelled'],'completed'=>[],'cancelled'=>[]];public function canTransition(string$f,string$t):bool{TaskStatus::assertValid($f);TaskStatus::assertValid($t);return in_array($t,self::T[$f],true);}public function assertTransition(string$f,string$t):void{if(!$this->canTransition($f,$t))throw new TaskTransitionException('transition_invalid');}}
